from pathlib import Path

ROOT = Path.cwd()

actions_path = ROOT / "app/(portal)/admin/crafting-recipes/actions.ts"
page_path = ROOT / "app/(portal)/admin/crafting-recipes/page.tsx"
form_path = ROOT / "components/admin/crafting-recipe-form.tsx"
layout_path = ROOT / "app/(portal)/admin/layout.tsx"

for path in (actions_path, page_path):
    if path.exists():
        raise SystemExit(f"ERROR: {path} already exists. No files were written.")

layout = layout_path.read_text(encoding="utf-8")

old = """  {can("items") ? (
    <AdminNavigationLink href="/admin/items">
      Items
    </AdminNavigationLink>
  ) : null}

  {can("jobs") ? ("""

new = """  {can("items") ? (
    <AdminNavigationLink href="/admin/items">
      Items
    </AdminNavigationLink>
  ) : null}

  {can("items") ? (
    <AdminNavigationLink href="/admin/crafting-recipes">
      Crafting Recipes
    </AdminNavigationLink>
  ) : null}

  {can("jobs") ? ("""

if layout.count(old) != 1:
    raise SystemExit(
        f"ERROR: Admin navigation anchor expected 1 match, found {layout.count(old)}. No files were written."
    )

layout = layout.replace(old, new, 1)

actions_path.parent.mkdir(parents=True, exist_ok=True)
form_path.parent.mkdir(parents=True, exist_ok=True)

actions_path.write_text('"use server";\n\nimport {\n  revalidatePath,\n} from "next/cache";\nimport { redirect } from "next/navigation";\n\nimport {\n  requireAdminSection,\n} from "@/lib/auth/require-staff";\nimport { createClient } from "@/lib/supabase/server";\n\nfunction text(\n  formData: FormData,\n  name: string,\n) {\n  const value =\n    formData.get(name);\n\n  return typeof value === "string"\n    ? value.trim()\n    : "";\n}\n\nfunction positiveInteger(\n  value: string,\n  label: string,\n) {\n  const parsed =\n    Number.parseInt(value, 10);\n\n  if (\n    !Number.isFinite(parsed) ||\n    parsed < 1\n  ) {\n    throw new Error(\n      `${label} must be at least 1.`,\n    );\n  }\n\n  return parsed;\n}\n\nfunction integer(\n  value: string,\n  fallback = 0,\n) {\n  if (!value.trim()) {\n    return fallback;\n  }\n\n  const parsed =\n    Number.parseInt(value, 10);\n\n  return Number.isFinite(parsed)\n    ? parsed\n    : fallback;\n}\n\nfunction slugify(\n  value: string,\n) {\n  return value\n    .trim()\n    .toLowerCase()\n    .normalize("NFKD")\n    .replace(\n      /[\\u0300-\\u036f]/g,\n      "",\n    )\n    .replace(\n      /[^a-z0-9]+/g,\n      "-",\n    )\n    .replace(\n      /^-+|-+$/g,\n      "",\n    );\n}\n\nfunction isUuid(\n  value: string,\n) {\n  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(\n    value,\n  );\n}\n\nfunction fail(\n  message: string,\n): never {\n  const params =\n    new URLSearchParams();\n\n  params.set(\n    "error",\n    message,\n  );\n\n  redirect(\n    `/admin/crafting-recipes?${params.toString()}`,\n  );\n}\n\nfunction refresh() {\n  revalidatePath(\n    "/admin/crafting-recipes",\n  );\n  revalidatePath(\n    "/admin/items",\n  );\n  revalidatePath(\n    "/crafting",\n  );\n}\n\ntype IngredientInput = {\n  itemId: string;\n  quantity: number;\n  sortOrder: number;\n};\n\nasync function recipeValues(\n  formData: FormData,\n) {\n  const name =\n    text(formData, "name");\n\n  if (!name) {\n    throw new Error(\n      "Recipe name is required.",\n    );\n  }\n\n  const slug =\n    slugify(\n      text(formData, "slug") ||\n        name,\n    );\n\n  if (!slug) {\n    throw new Error(\n      "A valid recipe slug is required.",\n    );\n  }\n\n  const resultItemId =\n    text(\n      formData,\n      "resultItemId",\n    );\n\n  if (\n    !isUuid(resultItemId)\n  ) {\n    throw new Error(\n      "A valid result Item is required.",\n    );\n  }\n\n  const resultQuantity =\n    positiveInteger(\n      text(\n        formData,\n        "resultQuantity",\n      ),\n      "Result quantity",\n    );\n\n  const ingredientItemIds =\n    formData\n      .getAll(\n        "ingredientItemId",\n      )\n      .map((value) =>\n        typeof value === "string"\n          ? value.trim()\n          : "",\n      );\n\n  const ingredientQuantities =\n    formData\n      .getAll(\n        "ingredientQuantity",\n      )\n      .map((value) =>\n        typeof value === "string"\n          ? value.trim()\n          : "",\n      );\n\n  const ingredients:\n    IngredientInput[] = [];\n\n  for (\n    let index = 0;\n    index <\n    ingredientItemIds.length;\n    index += 1\n  ) {\n    const itemId =\n      ingredientItemIds[\n        index\n      ] ?? "";\n\n    const rawQuantity =\n      ingredientQuantities[\n        index\n      ] ?? "";\n\n    if (\n      !itemId &&\n      !rawQuantity\n    ) {\n      continue;\n    }\n\n    if (\n      !isUuid(itemId)\n    ) {\n      throw new Error(\n        `Ingredient ${index + 1} is invalid.`,\n      );\n    }\n\n    ingredients.push({\n      itemId,\n      quantity:\n        positiveInteger(\n          rawQuantity,\n          `Ingredient ${index + 1} quantity`,\n        ),\n      sortOrder: index,\n    });\n  }\n\n  if (!ingredients.length) {\n    throw new Error(\n      "A crafting recipe needs at least one Ingredient.",\n    );\n  }\n\n  const uniqueIds =\n    new Set(\n      ingredients.map(\n        (ingredient) =>\n          ingredient.itemId,\n      ),\n    );\n\n  if (\n    uniqueIds.size !==\n    ingredients.length\n  ) {\n    throw new Error(\n      "The same Ingredient cannot be added twice. Increase its quantity instead.",\n    );\n  }\n\n  const supabase =\n    await createClient();\n\n  const {\n    data: resultItem,\n    error: resultError,\n  } = await supabase\n    .from("items")\n    .select(\n      "id, teaches_recipe_id",\n    )\n    .eq(\n      "id",\n      resultItemId,\n    )\n    .maybeSingle();\n\n  if (\n    resultError ||\n    !resultItem\n  ) {\n    throw new Error(\n      "The selected result Item could not be found.",\n    );\n  }\n\n  if (\n    resultItem\n      .teaches_recipe_id\n  ) {\n    throw new Error(\n      "Recipe and Pattern Items cannot be crafted as recipe outputs.",\n    );\n  }\n\n  const {\n    data: ingredientCategory,\n    error:\n      ingredientCategoryError,\n  } = await supabase\n    .from(\n      "item_categories",\n    )\n    .select("id")\n    .eq(\n      "slug",\n      "ingredient",\n    )\n    .maybeSingle();\n\n  if (\n    ingredientCategoryError ||\n    !ingredientCategory\n  ) {\n    throw new Error(\n      "The Ingredient Item category could not be found.",\n    );\n  }\n\n  const {\n    data: ingredientItems,\n    error:\n      ingredientItemsError,\n  } = await supabase\n    .from("items")\n    .select(\n      "id, category_id",\n    )\n    .in(\n      "id",\n      [\n        ...uniqueIds,\n      ],\n    );\n\n  if (\n    ingredientItemsError\n  ) {\n    throw new Error(\n      "Unable to validate recipe Ingredients.",\n    );\n  }\n\n  if (\n    (ingredientItems ?? [])\n      .length !==\n    uniqueIds.size\n  ) {\n    throw new Error(\n      "One or more selected Ingredients no longer exist.",\n    );\n  }\n\n  if (\n    (ingredientItems ?? [])\n      .some(\n        (item) =>\n          item.category_id !==\n          ingredientCategory.id,\n      )\n  ) {\n    throw new Error(\n      "Only Items in the Ingredient category can be used as recipe Ingredients.",\n    );\n  }\n\n  return {\n    recipe: {\n      name,\n      slug,\n      description:\n        text(\n          formData,\n          "description",\n        ),\n      result_item_id:\n        resultItemId,\n      result_quantity:\n        resultQuantity,\n      is_active:\n        formData.get(\n          "isActive",\n        ) === "on",\n      sort_order:\n        integer(\n          text(\n            formData,\n            "sortOrder",\n          ),\n          0,\n        ),\n      updated_at:\n        new Date().toISOString(),\n    },\n    ingredients,\n  };\n}\n\nexport async function createCraftingRecipe(\n  formData: FormData,\n) {\n  await requireAdminSection(\n    "items",\n  );\n\n  const supabase =\n    await createClient();\n\n  try {\n    const values =\n      await recipeValues(\n        formData,\n      );\n\n    const {\n      data: recipe,\n      error: recipeError,\n    } = await supabase\n      .from(\n        "crafting_recipes",\n      )\n      .insert(\n        values.recipe,\n      )\n      .select("id")\n      .single();\n\n    if (\n      recipeError ||\n      !recipe\n    ) {\n      throw new Error(\n        recipeError?.message ??\n          "Unable to create the crafting recipe.",\n      );\n    }\n\n    const {\n      error:\n        ingredientsError,\n    } = await supabase\n      .from(\n        "crafting_recipe_ingredients",\n      )\n      .insert(\n        values.ingredients.map(\n          (\n            ingredient,\n          ) => ({\n            recipe_id:\n              recipe.id,\n            ingredient_item_id:\n              ingredient.itemId,\n            quantity:\n              ingredient.quantity,\n            sort_order:\n              ingredient.sortOrder,\n          }),\n        ),\n      );\n\n    if (\n      ingredientsError\n    ) {\n      await supabase\n        .from(\n          "crafting_recipes",\n        )\n        .delete()\n        .eq(\n          "id",\n          recipe.id,\n        );\n\n      throw new Error(\n        ingredientsError.message,\n      );\n    }\n\n    refresh();\n  } catch (error) {\n    fail(\n      error instanceof Error\n        ? error.message\n        : "Unable to create the crafting recipe.",\n    );\n  }\n\n  redirect(\n    "/admin/crafting-recipes",\n  );\n}\n\nexport async function updateCraftingRecipe(\n  formData: FormData,\n) {\n  await requireAdminSection(\n    "items",\n  );\n\n  const recipeId =\n    text(\n      formData,\n      "recipeId",\n    );\n\n  if (!isUuid(recipeId)) {\n    fail(\n      "Invalid crafting recipe.",\n    );\n  }\n\n  const supabase =\n    await createClient();\n\n  try {\n    const values =\n      await recipeValues(\n        formData,\n      );\n\n    const {\n      error: recipeError,\n    } = await supabase\n      .from(\n        "crafting_recipes",\n      )\n      .update(\n        values.recipe,\n      )\n      .eq(\n        "id",\n        recipeId,\n      );\n\n    if (recipeError) {\n      throw new Error(\n        recipeError.message,\n      );\n    }\n\n    const {\n      error: deleteError,\n    } = await supabase\n      .from(\n        "crafting_recipe_ingredients",\n      )\n      .delete()\n      .eq(\n        "recipe_id",\n        recipeId,\n      );\n\n    if (deleteError) {\n      throw new Error(\n        deleteError.message,\n      );\n    }\n\n    const {\n      error: insertError,\n    } = await supabase\n      .from(\n        "crafting_recipe_ingredients",\n      )\n      .insert(\n        values.ingredients.map(\n          (\n            ingredient,\n          ) => ({\n            recipe_id:\n              recipeId,\n            ingredient_item_id:\n              ingredient.itemId,\n            quantity:\n              ingredient.quantity,\n            sort_order:\n              ingredient.sortOrder,\n          }),\n        ),\n      );\n\n    if (insertError) {\n      throw new Error(\n        insertError.message,\n      );\n    }\n\n    refresh();\n  } catch (error) {\n    fail(\n      error instanceof Error\n        ? error.message\n        : "Unable to update the crafting recipe.",\n    );\n  }\n\n  redirect(\n    "/admin/crafting-recipes",\n  );\n}\n\nexport async function deleteCraftingRecipe(\n  formData: FormData,\n) {\n  await requireAdminSection(\n    "items",\n  );\n\n  const recipeId =\n    text(\n      formData,\n      "recipeId",\n    );\n\n  if (!isUuid(recipeId)) {\n    fail(\n      "Invalid crafting recipe.",\n    );\n  }\n\n  const supabase =\n    await createClient();\n\n  try {\n    const {\n      count,\n      error: knownError,\n    } = await supabase\n      .from(\n        "character_recipes",\n      )\n      .select(\n        "id",\n        {\n          count: "exact",\n          head: true,\n        },\n      )\n      .eq(\n        "recipe_id",\n        recipeId,\n      );\n\n    if (knownError) {\n      throw new Error(\n        knownError.message,\n      );\n    }\n\n    if (\n      (count ?? 0) > 0\n    ) {\n      throw new Error(\n        "This recipe is already known by one or more characters. Mark it Inactive instead of deleting it.",\n      );\n    }\n\n    const {\n      error,\n    } = await supabase\n      .from(\n        "crafting_recipes",\n      )\n      .delete()\n      .eq(\n        "id",\n        recipeId,\n      );\n\n    if (error) {\n      throw new Error(\n        error.message,\n      );\n    }\n\n    refresh();\n  } catch (error) {\n    fail(\n      error instanceof Error\n        ? error.message\n        : "Unable to delete the crafting recipe.",\n    );\n  }\n\n  redirect(\n    "/admin/crafting-recipes",\n  );\n}\n', encoding="utf-8")
page_path.write_text('import {\n  CraftingRecipeForm,\n  type CraftingRecipeIngredientValue,\n  type CraftingRecipeItemOption,\n} from "@/components/admin/crafting-recipe-form";\nimport {\n  AdminActionForm,\n} from "@/components/admin/admin-action-form";\nimport {\n  requireAdminSection,\n} from "@/lib/auth/require-staff";\nimport { createClient } from "@/lib/supabase/server";\n\nimport {\n  createCraftingRecipe,\n  deleteCraftingRecipe,\n  updateCraftingRecipe,\n} from "./actions";\n\ntype Props = {\n  searchParams?: Promise<{\n    error?: string;\n  }>;\n};\n\ntype RecipeRow = {\n  id: string;\n  name: string;\n  slug: string;\n  description: string;\n  result_item_id: string;\n  result_quantity: number;\n  is_active: boolean;\n  sort_order: number;\n};\n\ntype IngredientRow = {\n  recipe_id: string;\n  ingredient_item_id: string;\n  quantity: number;\n  sort_order: number;\n};\n\nexport default async function AdminCraftingRecipesPage({\n  searchParams,\n}: Props) {\n  await requireAdminSection(\n    "items",\n  );\n\n  const params =\n    (await searchParams) ??\n    {};\n\n  const supabase =\n    await createClient();\n\n  const [\n    ingredientCategoryResult,\n    itemsResult,\n    recipesResult,\n    ingredientsResult,\n  ] = await Promise.all([\n    supabase\n      .from(\n        "item_categories",\n      )\n      .select("id")\n      .eq(\n        "slug",\n        "ingredient",\n      )\n      .maybeSingle(),\n\n    supabase\n      .from("items")\n      .select(\n        "id, name, slug, image_url, is_active, category_id, teaches_recipe_id",\n      )\n      .order(\n        "name",\n        {\n          ascending: true,\n        },\n      ),\n\n    supabase\n      .from(\n        "crafting_recipes",\n      )\n      .select(\n        "id, name, slug, description, result_item_id, result_quantity, is_active, sort_order",\n      )\n      .order(\n        "sort_order",\n        {\n          ascending: true,\n        },\n      )\n      .order(\n        "name",\n        {\n          ascending: true,\n        },\n      ),\n\n    supabase\n      .from(\n        "crafting_recipe_ingredients",\n      )\n      .select(\n        "recipe_id, ingredient_item_id, quantity, sort_order",\n      )\n      .order(\n        "sort_order",\n        {\n          ascending: true,\n        },\n      ),\n  ]);\n\n  const firstError =\n    ingredientCategoryResult.error ??\n    itemsResult.error ??\n    recipesResult.error ??\n    ingredientsResult.error;\n\n  if (firstError) {\n    throw new Error(\n      `Unable to load Crafting Recipes: ${firstError.message}`,\n    );\n  }\n\n  const ingredientCategoryId =\n    ingredientCategoryResult\n      .data?.id ??\n    null;\n\n  const allItems =\n    (itemsResult.data ??\n      []) as (\n      CraftingRecipeItemOption & {\n        category_id: string;\n        teaches_recipe_id:\n          | string\n          | null;\n      }\n    )[];\n\n  const resultItems =\n    allItems\n      .filter(\n        (item) =>\n          !item\n            .teaches_recipe_id,\n      )\n      .map(\n        ({\n          category_id:\n            _categoryId,\n          teaches_recipe_id:\n            _teachesRecipeId,\n          ...item\n        }) => item,\n      );\n\n  const ingredientItems =\n    allItems\n      .filter(\n        (item) =>\n          ingredientCategoryId &&\n          item.category_id ===\n            ingredientCategoryId,\n      )\n      .map(\n        ({\n          category_id:\n            _categoryId,\n          teaches_recipe_id:\n            _teachesRecipeId,\n          ...item\n        }) => item,\n      );\n\n  const recipes =\n    (recipesResult.data ??\n      []) as RecipeRow[];\n\n  const ingredientRows =\n    (ingredientsResult.data ??\n      []) as IngredientRow[];\n\n  const ingredientsByRecipe =\n    new Map<\n      string,\n      CraftingRecipeIngredientValue[]\n    >();\n\n  for (\n    const row of\n    ingredientRows\n  ) {\n    const current =\n      ingredientsByRecipe.get(\n        row.recipe_id,\n      ) ?? [];\n\n    current.push({\n      itemId:\n        row.ingredient_item_id,\n      quantity:\n        row.quantity,\n    });\n\n    ingredientsByRecipe.set(\n      row.recipe_id,\n      current,\n    );\n  }\n\n  const itemNameById =\n    new Map(\n      allItems.map(\n        (item) => [\n          item.id,\n          item.name,\n        ],\n      ),\n    );\n\n  return (\n    <main className="p-5 sm:p-7 lg:p-9">\n      <div className="mx-auto max-w-7xl">\n        <div>\n          <p className="text-[9px] uppercase tracking-[0.28em] text-[rgb(var(--sep-colour-8c704b))]">\n            Administration\n          </p>\n\n          <h1 className="mt-2 font-serif text-4xl text-[rgb(var(--sep-colour-ead5ac))]">\n            Crafting Recipes\n          </h1>\n\n          <p className="mt-3 max-w-4xl text-sm leading-7 text-[rgb(var(--sep-colour-a99b89))]">\n            Define the formulas characters can learn and craft.\n            Choose the resulting Item, its quantity, and the\n            Ingredient-category Items required to make it. Physical\n            Recipe or Pattern Items are linked separately through\n            Item Management.\n          </p>\n        </div>\n\n        {params.error ? (\n          <div className="mt-6 border border-red-900/60 bg-red-950/20 px-4 py-3 text-sm text-red-400">\n            {params.error}\n          </div>\n        ) : null}\n\n        <section className="mt-8 border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-15100d))] p-5 sm:p-6">\n          <p className="text-[9px] uppercase tracking-[0.24em] text-[rgb(var(--sep-colour-8c704b))]">\n            New Formula\n          </p>\n\n          <h2 className="mt-2 font-serif text-2xl text-[rgb(var(--sep-colour-dfc99f))]">\n            Create Crafting Recipe\n          </h2>\n\n          <CraftingRecipeForm\n            action={\n              createCraftingRecipe\n            }\n            resultItems={\n              resultItems\n            }\n            ingredientItems={\n              ingredientItems\n            }\n            submitLabel="Create Recipe"\n          />\n        </section>\n\n        <div className="mt-6 space-y-4">\n          {recipes.map(\n            (recipe) => {\n              const ingredients =\n                ingredientsByRecipe.get(\n                  recipe.id,\n                ) ?? [];\n\n              return (\n                <details\n                  key={\n                    recipe.id\n                  }\n                  className="border border-[rgb(var(--sep-colour-59432c))]/45 bg-[rgb(var(--sep-colour-100c09))]"\n                >\n                  <summary className="cursor-pointer list-none px-4 py-4">\n                    <div className="flex flex-wrap items-center justify-between gap-4">\n                      <div className="min-w-0">\n                        <p className="font-serif text-lg text-[rgb(var(--sep-colour-d8bf91))]">\n                          {\n                            recipe.name\n                          }\n                        </p>\n\n                        <p className="mt-1 text-[8px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-766956))]">\n                          Produces{" "}\n                          {\n                            recipe.result_quantity\n                          }{" "}\n                          ×{" "}\n                          {itemNameById.get(\n                            recipe.result_item_id,\n                          ) ??\n                            "Unknown Item"}\n                          {" · "}\n                          {\n                            ingredients.length\n                          }{" "}\n                          ingredient\n                          {ingredients.length ===\n                          1\n                            ? ""\n                            : "s"}\n                        </p>\n                      </div>\n\n                      <span className="text-[8px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-9b8768))]">\n                        {recipe.is_active\n                          ? "Active"\n                          : "Inactive"}\n                      </span>\n                    </div>\n                  </summary>\n\n                  <div className="border-t border-[rgb(var(--sep-colour-59432c))]/35 p-4 sm:p-5">\n                    <CraftingRecipeForm\n                      action={\n                        updateCraftingRecipe\n                      }\n                      recipeId={\n                        recipe.id\n                      }\n                      defaultName={\n                        recipe.name\n                      }\n                      defaultSlug={\n                        recipe.slug\n                      }\n                      defaultDescription={\n                        recipe.description\n                      }\n                      defaultResultItemId={\n                        recipe.result_item_id\n                      }\n                      defaultResultQuantity={\n                        recipe.result_quantity\n                      }\n                      defaultSortOrder={\n                        recipe.sort_order\n                      }\n                      defaultActive={\n                        recipe.is_active\n                      }\n                      defaultIngredients={\n                        ingredients\n                      }\n                      resultItems={\n                        resultItems\n                      }\n                      ingredientItems={\n                        ingredientItems\n                      }\n                      submitLabel="Save Recipe"\n                    />\n\n                    <div className="mt-5 flex justify-end border-t border-[rgb(var(--sep-colour-59432c))]/35 pt-5">\n                      <AdminActionForm\n                        action={\n                          deleteCraftingRecipe\n                        }\n                        confirmMessage={`Are you sure you want to permanently delete "${recipe.name}"?`}\n                      >\n                        <input\n                          type="hidden"\n                          name="recipeId"\n                          value={\n                            recipe.id\n                          }\n                        />\n\n                        <button\n                          type="submit"\n                          className="border border-red-900/55 bg-red-950/20 px-4 py-2 text-[8px] uppercase tracking-[0.14em] text-red-300"\n                        >\n                          Delete Recipe\n                        </button>\n                      </AdminActionForm>\n                    </div>\n                  </div>\n                </details>\n              );\n            },\n          )}\n        </div>\n      </div>\n    </main>\n  );\n}\n', encoding="utf-8")
form_path.write_text('"use client";\n\nimport {\n  useState,\n} from "react";\n\nimport {\n  AdminActionForm,\n} from "@/components/admin/admin-action-form";\n\nexport type CraftingRecipeItemOption = {\n  id: string;\n  name: string;\n  slug: string;\n  image_url: string | null;\n  is_active: boolean;\n};\n\nexport type CraftingRecipeIngredientValue = {\n  itemId: string;\n  quantity: number;\n};\n\ntype Props = {\n  action: (\n    formData: FormData,\n  ) => Promise<void>;\n  recipeId?: string;\n  defaultName?: string;\n  defaultSlug?: string;\n  defaultDescription?: string;\n  defaultResultItemId?: string;\n  defaultResultQuantity?: number;\n  defaultSortOrder?: number;\n  defaultActive?: boolean;\n  defaultIngredients?: CraftingRecipeIngredientValue[];\n  resultItems: CraftingRecipeItemOption[];\n  ingredientItems: CraftingRecipeItemOption[];\n  submitLabel: string;\n};\n\nconst inputClass =\n  "w-full border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-100c09))] px-3 py-2.5 text-sm text-[rgb(var(--sep-colour-d7c4a5))] outline-none placeholder:text-[rgb(var(--sep-colour-625747))] focus:border-[rgb(var(--sep-colour-a17a49))]";\n\nconst buttonClass =\n  "border border-[rgb(var(--sep-colour-987344))] bg-[rgb(var(--sep-colour-3b2919))] px-4 py-2.5 text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-efd6a8))] transition hover:bg-[rgb(var(--sep-colour-4a321e))]";\n\nexport function CraftingRecipeForm({\n  action,\n  recipeId,\n  defaultName = "",\n  defaultSlug = "",\n  defaultDescription = "",\n  defaultResultItemId = "",\n  defaultResultQuantity = 1,\n  defaultSortOrder = 0,\n  defaultActive = true,\n  defaultIngredients = [],\n  resultItems,\n  ingredientItems,\n  submitLabel,\n}: Props) {\n  const [\n    ingredients,\n    setIngredients,\n  ] = useState<\n    CraftingRecipeIngredientValue[]\n  >(\n    defaultIngredients.length\n      ? defaultIngredients\n      : [\n          {\n            itemId: "",\n            quantity: 1,\n          },\n        ],\n  );\n\n  function addIngredient() {\n    setIngredients(\n      (current) => [\n        ...current,\n        {\n          itemId: "",\n          quantity: 1,\n        },\n      ],\n    );\n  }\n\n  function removeIngredient(\n    index: number,\n  ) {\n    setIngredients(\n      (current) => {\n        const next =\n          current.filter(\n            (\n              _ingredient,\n              currentIndex,\n            ) =>\n              currentIndex !==\n              index,\n          );\n\n        return next.length\n          ? next\n          : [\n              {\n                itemId: "",\n                quantity: 1,\n              },\n            ];\n      },\n    );\n  }\n\n  function updateIngredient(\n    index: number,\n    patch: Partial<CraftingRecipeIngredientValue>,\n  ) {\n    setIngredients(\n      (current) =>\n        current.map(\n          (\n            ingredient,\n            currentIndex,\n          ) =>\n            currentIndex ===\n            index\n              ? {\n                  ...ingredient,\n                  ...patch,\n                }\n              : ingredient,\n        ),\n    );\n  }\n\n  return (\n    <AdminActionForm\n      action={action}\n      className="mt-5"\n    >\n      {recipeId ? (\n        <input\n          type="hidden"\n          name="recipeId"\n          value={recipeId}\n        />\n      ) : null}\n\n      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">\n        <Field label="Recipe name">\n          <input\n            name="name"\n            required\n            defaultValue={\n              defaultName\n            }\n            className={\n              inputClass\n            }\n          />\n        </Field>\n\n        <Field label="Slug">\n          <input\n            name="slug"\n            defaultValue={\n              defaultSlug\n            }\n            placeholder="Auto from recipe name"\n            className={\n              inputClass\n            }\n          />\n        </Field>\n\n        <Field label="Crafted result Item">\n          <select\n            name="resultItemId"\n            required\n            defaultValue={\n              defaultResultItemId\n            }\n            className={\n              inputClass\n            }\n          >\n            <option\n              value=""\n              disabled\n            >\n              Select Item\n            </option>\n\n            {resultItems.map(\n              (item) => (\n                <option\n                  key={\n                    item.id\n                  }\n                  value={\n                    item.id\n                  }\n                >\n                  {item.name}\n                  {!item.is_active\n                    ? " (inactive)"\n                    : ""}\n                </option>\n              ),\n            )}\n          </select>\n        </Field>\n\n        <Field label="Result quantity">\n          <input\n            type="number"\n            name="resultQuantity"\n            min={1}\n            required\n            defaultValue={\n              defaultResultQuantity\n            }\n            className={\n              inputClass\n            }\n          />\n        </Field>\n\n        <div className="md:col-span-2 xl:col-span-4">\n          <Field label="Description">\n            <textarea\n              name="description"\n              rows={3}\n              defaultValue={\n                defaultDescription\n              }\n              className={\n                inputClass\n              }\n            />\n          </Field>\n        </div>\n\n        <Field label="Sort order">\n          <input\n            type="number"\n            name="sortOrder"\n            defaultValue={\n              defaultSortOrder\n            }\n            className={\n              inputClass\n            }\n          />\n        </Field>\n\n        <div className="flex items-end pb-2">\n          <label className="flex items-center gap-2 text-[9px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-aa9473))]">\n            <input\n              type="checkbox"\n              name="isActive"\n              defaultChecked={\n                defaultActive\n              }\n            />\n            Active\n          </label>\n        </div>\n      </div>\n\n      <div className="mt-6 border-t border-[rgb(var(--sep-colour-59432c))]/35 pt-5">\n        <div className="flex flex-wrap items-center justify-between gap-3">\n          <div>\n            <p className="text-[8px] uppercase tracking-[0.2em] text-[rgb(var(--sep-colour-8c704b))]">\n              Formula\n            </p>\n\n            <h3 className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-d8bf91))]">\n              Required Ingredients\n            </h3>\n          </div>\n\n          <button\n            type="button"\n            onClick={\n              addIngredient\n            }\n            className={\n              buttonClass\n            }\n          >\n            + Ingredient\n          </button>\n        </div>\n\n        <div className="mt-4 space-y-2">\n          {ingredients.map(\n            (\n              ingredient,\n              index,\n            ) => (\n              <div\n                key={index}\n                className="grid gap-2 border border-[rgb(var(--sep-colour-59432c))]/35 bg-[rgb(var(--sep-colour-100c09))] p-3 sm:grid-cols-[minmax(0,1fr)_110px_auto]"\n              >\n                <select\n                  name="ingredientItemId"\n                  required\n                  value={\n                    ingredient.itemId\n                  }\n                  onChange={(\n                    event,\n                  ) =>\n                    updateIngredient(\n                      index,\n                      {\n                        itemId:\n                          event\n                            .target\n                            .value,\n                      },\n                    )\n                  }\n                  className={\n                    inputClass\n                  }\n                >\n                  <option\n                    value=""\n                    disabled\n                  >\n                    Select Ingredient\n                  </option>\n\n                  {ingredientItems.map(\n                    (item) => (\n                      <option\n                        key={\n                          item.id\n                        }\n                        value={\n                          item.id\n                        }\n                      >\n                        {item.name}\n                        {!item.is_active\n                          ? " (inactive)"\n                          : ""}\n                      </option>\n                    ),\n                  )}\n                </select>\n\n                <input\n                  type="number"\n                  name="ingredientQuantity"\n                  min={1}\n                  required\n                  value={\n                    ingredient.quantity\n                  }\n                  onChange={(\n                    event,\n                  ) =>\n                    updateIngredient(\n                      index,\n                      {\n                        quantity:\n                          Number.parseInt(\n                            event\n                              .target\n                              .value,\n                            10,\n                          ) ||\n                          1,\n                      },\n                    )\n                  }\n                  className={\n                    inputClass\n                  }\n                  aria-label={`Ingredient ${index + 1} quantity`}\n                />\n\n                <button\n                  type="button"\n                  onClick={() =>\n                    removeIngredient(\n                      index,\n                    )\n                  }\n                  className="border border-red-900/55 bg-red-950/20 px-3 py-2 text-[8px] uppercase tracking-[0.14em] text-red-300"\n                >\n                  Remove\n                </button>\n              </div>\n            ),\n          )}\n        </div>\n      </div>\n\n      <div className="mt-5 flex justify-end border-t border-[rgb(var(--sep-colour-59432c))]/35 pt-5">\n        <button\n          type="submit"\n          className={\n            buttonClass\n          }\n        >\n          {submitLabel}\n        </button>\n      </div>\n    </AdminActionForm>\n  );\n}\n\nfunction Field({\n  label,\n  children,\n}: {\n  label: string;\n  children: React.ReactNode;\n}) {\n  return (\n    <label className="block">\n      <span className="mb-2 block text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-806b50))]">\n        {label}\n      </span>\n\n      {children}\n    </label>\n  );\n}\n', encoding="utf-8")
layout_path.write_text(layout, encoding="utf-8")

